    "full_desc": "Сдаётся студия на 7-м этаже. Что есть в квартире: -Стиральная машина -Телевизор -Микроволновка -Электрическая конфорка -Электрический чайник -Холодильник -Шкаф -Диван -Кухонная зона (посуды на текущей момент нет) - Обувница В общем, всё что видно на фото. Условия аренды: Стоимость: 20 000 ₽ в месяц. Залог: 10 000 ₽, единоразово. Коммунальные платежи: оплачиваются отдельно по счётчикам: горячая вода, холодная вода, электроэнергия. Остальные платежи (отопление, ТКО, управляющей компании и т.д. - оплачиваем мы). Срок аренды: желательно длительный, обсуждаемо. Дата оплаты: можно согласовать под ваш график, например, под дату получения зарплаты. Проживание с животными: по договорённости. Можно заселиться одному, паре или семье. Договор официальный, налоги уплачиваются. Квартира принадлежит моему отцу, а я занимаюсь сдачей по нотариальной доверенности, поскольку он часто находится в разъездах. По всем вопросам пишите в личные сообщения или звоните Дополнительная информация: Стиральная машина, Телевизор, Интернет. Косметический ремонт. Необходим залог, 10000 р.",
