    "desc_short": "Собственник. Комната расположена на верхнем этаже с очень высокими потолками (3.8 метра) в секции из 4 квартир. Отдельный замок, как на двер...",
    "full_desc": "Собственник. Комната расположена на верхнем этаже с очень высокими потолками (3.8 метра) в секции из 4 квартир. Отдельный замок, как на двери в комнату, так и на двери в саму секцию. Туалет общий на 3 квартиры (у 4ой свой). Душа/ванны, к сожалению, именно в нашей комнате нет. Но совсем рядом есть Бани 2 и 5 с общими отделениями, есть просто душ в банном комплексе Аврора (300 руб за 30 мин), есть сауна \"Ибица\" и прочие. В самой комнате проведена только холодная вода, но установлен проточный водонагреватель. Есть стиральная машина, холодильник, чайник, 2х конфорочная плитка, микроволновка, пылесос, утюг, различная мебель (диван раскладывается) и прочее по мелочи (например: посуда, одеяло, плед, подушки, постельное, гладильная доска, настенная сушилка, жалюзи). В целом, почти всё видно на фото. Также, установлено пластиковое окно с напылением от тепловых лучей (так как сторона солнечная). Зимой очень хорошо отапливается весь дом. В квартирах бывает жарко. Соседи в секции все возрастные люди, не шумят и не беспокоят. В ответ ждут того же. Расположение дома рядом с ТГАСУ, Белым озером, Областным судом. Пара минут ходьбы до магазина Монетка и прочих. Жильё сдаётся только на длительный срок от 3 месяцев минимум. Стоимость в месяц будет составлять 13 000 рублей. Вся коммуналка входит в цену. Также, нужен будет залог 3000 рублей, который возвращается при выезде жильцу. Предупреждать о выезде нужно будет как минимум за 2 недели. НЕ запрещено заселиться с детьми или животными. Просмотр возможен в любое время, но по договорённости. Звоните или пишите. Буду рада ответить на все вопросы. Дополнительная информация: холодильник, мебель, интернет, микроволновая печь, пластиковые окна, кухонная плита, стиральная машина",
