    "full_desc": "Собственник! Сдается уютная двухкомнатная квартира на длительный срок. Дом панельного типа, построенный в 2008 году. В квартире выполнен косметический ремонт, комнаты изолированы. Из мебели имеются шкафы и диван, а также телевизор. Кухня компактная, площадью 5 кв.м., оборудована необходимой техникой: холодильник, плита, микроволновка. Под паласами лежит красивый линолеум, паласы можно убрать при желании Ванная комната совмещенная, установлена душевая кабина. В квартире есть балкон с выходом из гостиной, где можно обустроить зону отдыха. Дом оснащен пассажирским лифтом, имеется открытая парковка во дворе. Курение запрещено, возможно проживание с детьми, но без животных. Дополнительная информация: кухонная плита, микроволновая печь, пластиковые окна, телевизор, стиральная машина, мебель, холодильник",
