    "desc_short": "Сдается однокомнатная квартира на длительный срок порядочным, семейным, без животных \nВ квартире есть все необходимое, два дивана, стиральна...",
    "full_desc": "Сдается однокомнатная квартира на длительный срок порядочным, семейным, без животных \nВ квартире есть все необходимое, два дивана, стиральная машина, бойлер,микроволновая печь, холодильник, электрическая плита, чайник\nВидеонаблюдение по периметру дома, грузопассажирский лифт\nВо дворе большая парковка, детская площадка \nВся инфраструктура в шаговой доступности, супермаркеты, аптеки, кафе, озон и вайлдберис \nКвартира готова к заселению \nПо всем вопросам звонить или писать\nЗалог можно разделить на два месяца",
