    "desc_short": "Сдаётся просторная студия площадью 56 кв. м на последнем, 11 этаже кирпичного дома. Дом построен в 2011 году. Высота потолков составляет 2.7...",
    "full_desc": "Сдаётся просторная студия площадью 56 кв. м на последнем, 11 этаже кирпичного дома. Дом построен в 2011 году. Высота потолков составляет 2.7 метра, что даёт ощущение простора и уюта. Квартира предлагается напрямую от собственника. \n\nВ квартире выполнен косметический ремонт. Здесь есть вся необходимая мебель как в комнате, так и на кухне, что позволяет сразу заехать и жить. Для вашего удобства установлены холодильник, телевизор и стиральная машина. Ванная комната оборудована ванной, что обеспечивает комфортное использование.\n\nДом находится в хорошем состоянии и оборудован тремя лифтами: одним пассажирским и двумя грузовыми. Это удобно для транспортировки крупногабаритных вещей. \n\nВ шаговой доступности вы найдёте всё необходимое для комфортной жизни: школы, детские сады, клиники и магазины. Это делает район идеальным для семей и тех, кто ценит удобство городской инфраструктуры.\n\nЗаписывайтесь на просмотр и приходите оценить все преимущества этой студии лично.",
