    "address": "Россия, Томск, микрорайон Черемошники, улица 5-й Армии, 9",
    "metro_name": "Ленинский район",
    "metro_walk": "5 мин",
    "desc_short": "СОБСТВЕННИК НЕ АГЕНТСТВО!\nСдаётся на длительный срок полноценная 1-комнатная квартира (36,4 м²)\nСделан свежий ремонт.\nОписание: в квартире е...",
    "full_desc": "СОБСТВЕННИК НЕ АГЕНТСТВО!\nСдаётся на длительный срок полноценная 1-комнатная квартира (36,4 м²)\nСделан свежий ремонт.\nОписание: в квартире есть всё необходимое для комфортного проживания.\nПреимущества квартиры:\n* Тёплая и уютная атмосфера.\n* Застеклённый балкон с большой лоджией.\n* Евро радиатор в зале, пластиковые окна ( зимой даже отключаем радиаторы, очень тепло).\n* Установлен домофон, интернет и кабельное ТВ.\n* Новая проводка, сантехника и счётчики.\n* Выровненные стены, сейфовая входная дверь.\nРасположение: Квартира находится на среднем этаже дома. Соседи тихие и дружелюбные, в основном пожилые люди и семейные пары. Подъезд расположен удобно — крайний у въезда к дому, что обеспечивает лёгкий доступ.\nТранспортная доступность: Дом находится в очень удобном месте.\nВ шаговой доступности остановки общественного транспорта (маршруты 5, 12, 32, 20, 38) (троллейбус 2-ка), до центра города можно добраться за несколько минут.\nИнфраструктура: Рядом с домом расположены детский сад, школа, спорткомплекс Восход, семейный парк Дружба народов, библиотека, детская поликлиника и больница для взрослых. Всё это находится в шаговой доступности.\nВ доме есть социальная аптека, а рядом супермаркеты Ярче, Ozon, парикмахерские, Магнит, Мария-Ра, Овощи-фрукты и т.д\nДополнительные удобства:\n* Современный лифт в подъезде.\n* Недавно произведён ремонт крыши и замена стояков.\n* Ухоженная придомовая территория.\n* Новая детская площадка.\n* Окна выходят во двор, без шума машин и людей.\n* Квартира для тех, кто хочет  тишину и комфорт — без компромиссов в повседневной жизни.\nУсловия аренды:\n* Собственник, не агентство.\n* Сдаётся платёжеспособным, аккуратным и ответственным  арендаторам.\n* С просьбами прописать в квартире, мимо.\n* С животными не заселяю.\n* Оплата: 22 000 руб. + коммунальные услуги.\n* При заселении заключаем договор, вносите залог (депозит) 10 000 руб. при выселении возвращаются если соблюдены условия договора .\n-----\nПримечание: у собственника могут быть дополнительные пожелания к жильцам - обсудите их в чате или по телефону",
