    "desc_short": "Квартира готова к просмотру после 03.10. \n\nСдается уютная двухкомнатная квартира в центре города на центральном кольце. \nДо центральной площ...",
    "full_desc": "Квартира готова к просмотру после 03.10. \n\nСдается уютная двухкомнатная квартира в центре города на центральном кольце. \nДо центральной площади 10 минут пешком, до выезда из города ( до центрального КПП) 5-7 минут на автобусе/машине. \nДо остановки 1 минута, остановка прямо под окнами. \n\nВсе магазины в шаговой доступности магнит/пятёрочка/ярче/абрикос, spar.\n\nКвартира очень светлая, солнечная, уютная. \nРемонт был сделан для себя, жили очень комфортно. Соседи спокойные, тихие, есть вторая дверь входная на двух соседей. \n\nКухня оснащена всем необходимым: печь, микроволновка, раковина, гарнитур кухонный, чайник, холодильник. \n\nСанузел раздельный, большая ванная, стиральная машина фирмы AEG , хорошего качества. \n\nИз кухни и из зала есть выход на балкон, на балконе тёплый пол, зимой всегда комфортно можно находится, на балконе на стёклах есть жалюзи. \n\nВ зале есть диван, шкаф, стенка с телевизором, места для размещения одежды достаточно. \n\nВ спальне кровать с ортопедическим матрасом, компьютерный стол и шкаф. Кровать с подъёмным механизмом (дополнительное место, куда можно разместить вещи). \n\nВ коридоре также имеется стенка/шкафы, обувница и достаточно большое пространство. \n\nКвартира готова к заселению в любой момент, преимущественно сдается для семейной пары, семьи с детьми без животных. \nВсе обсуждается, звоните, на все вопросы отвечу. \n\nИнтернет в квартире есть. \n\nК/у, интернет не включены в стоимость, оплачиваются отдельно по квитанции. \n \nВсе квитанции, сколько по сумме получается зимой и летом могу показать, в среднем получается около 10000 все вместе зимой, летом чуть поменьше.",
