    "desc_short": "Сдаётся в аренду уютная 2-комнатная квартира в кирпичном доме. Квартира расположена на 1 этаже 12-этажного здания и имеет общую площадь 66,2...",
    "full_desc": "Сдаётся в аренду уютная 2-комнатная квартира в кирпичном доме. Квартира расположена на 1 этаже 12-этажного здания и имеет общую площадь 66,2 кв. м, из которых жилая площадь составляет 50 кв. м, а кухня - 11,3 кв. м. Благодаря окнам, выходящим во двор, в квартире всегда тихо и комфортно.\n\nВ квартире сделан евроремонт, что создаёт атмосферу уюта и стильного современного интерьера. Комнаты частично меблированы, в зале диван раскладной и 2 кресла,  телевизор. В спальне детский диван. Вместительная гардеробная , в коридоре шкаф купе , комод. Кухня пустая , но по догоаоренности установим кухню, есть плита, холодильник. Санузел совмещённый, в ванной комнате установлена полноценная ванна,  что идеально для расслабления после рабочего дня., стиральная машина.\n\nДом, в котором находится квартира, оснащён двумя пассажирскими лифтами и наземной парковкой, поэтому можно без проблем оставлять автомобиль рядом с домом. Кирпичные стены обеспечивают хорошую звукоизоляцию и тепло в зимний период.\n\nРайон отличается развитой инфраструктурой: в шаговой доступности находятся школы, детские сады и клиники. Также поблизости есть магазины, где можно купить всё необходимое. Отличная транспортная доступность позволит быстро добраться в любую часть города.\n\nАренда напрямую от собственника, без посредников. С условиями аренды можно ознакомиться при личной встречи. Депозит есть. Квартира идеально подойдёт для семьи или пары.\n\nЗаписывайтесь на просмотр, чтобы вживую оценить все преимущества этой квартиры и её окружения. Мы ждём вас!",
