    "full_desc": "Предлагаем арендовать уютную 2-комнатную квартиру площадью 53 кв. м на первом этаже 11-этажного панельного дома. Квартира находится по адресу: Россия, Томская область, Северск, Северная улица, 30. Год постройки дома — 1996.\n\nВ квартире сделан косметический ремонт. Просторная кухня площадью 9 кв. м оборудована всей необходимой мебелью и техникой, включая холодильник и стиральную машину. Ванная комната оснащена ванной. В одной из комнат также есть мебель для комфортного проживания. Из окон открывается вид на улицу, что добавляет свет и уют В квартире есть все необходимое для проживания(мебель, посуда, бытовая техника, постельное белье)\n\nДом в хорошем состоянии, оснащён пассажирским лифтом и мусоропроводом. Есть лоджия, где можно отдохнуть или устроить небольшую зону отдыха. \n\nРядом с домом расположены школы, детские сады, клиники и магазины. Это удобно для семей с детьми и тех, кто ценит близость инфраструктуры.\n\nДоговор заключается с собственником. \n\nПриглашаем вас на просмотр квартиры! Свяжитесь с нами, чтобы договориться о времени визита.",
